<?php

namespace Tests\Unit;

use App\Sales\Pricing;
use App\Sync\EventValidator;
use PHPUnit\Framework\Attributes\DataProvider;
use Tests\TestCase;

/**
 * The TypeScript core is the source of truth for pricing and sale validation;
 * these vectors are generated by packages/core/test/vectors.test.ts.
 */
class SharedVectorTest extends TestCase
{
    private static function vectors(string $file): mixed
    {
        return json_decode((string) file_get_contents(dirname(__DIR__, 4)."/packages/core/test-vectors/{$file}"), flags: JSON_THROW_ON_ERROR);
    }

    public static function pricingCases(): iterable
    {
        foreach (self::vectors('pricing.v1.json') as $i => $case) {
            $in = $case->input;
            yield "#{$i} {$in->unitPriceMinor}x{$in->quantityMilli} {$in->rounding}" => [$case];
        }
    }

    #[DataProvider('pricingCases')]
    public function test_pricing_matches_typescript(object $case): void
    {
        $in = $case->input;
        $out = Pricing::priceLine($in->unitPriceMinor, $in->quantityMilli, $in->discountMinor, $in->taxRateBasisPoints, $in->taxInclusive, $in->rounding);

        $this->assertSame((array) $case->output, $out);
    }

    public static function saleCases(): iterable
    {
        foreach (self::vectors('sale-events.v1.json') as $case) {
            yield $case->name => [$case];
        }
    }

    #[DataProvider('saleCases')]
    public function test_sale_validation_matches_typescript(object $case): void
    {
        $problems = app(EventValidator::class)->validate($case->event);

        $this->assertSame($case->valid, $problems === [], implode("\n", $problems) ?: 'expected problems, found none');
    }

    public function test_api_schema_copy_matches_the_core(): void
    {
        $this->assertFileEquals(
            dirname(__DIR__, 4).'/packages/core/schema/sync-push-request.v1.json',
            resource_path('schemas/sync-push-request.v1.json'),
            'Copy packages/core/schema/sync-push-request.v1.json to apps/api/resources/schemas/.',
        );
    }

    public function test_canonical_hash_ignores_key_order(): void
    {
        $a = json_decode('{"b":1,"a":{"y":[1,{"q":2,"p":1}],"x":"é/"}}');
        $b = json_decode('{"a":{"x":"é/","y":[1,{"p":1,"q":2}]},"b":1}');
        $c = json_decode('{"a":{"x":"é/","y":[{"p":1,"q":2},1]},"b":1}');

        $this->assertSame(EventValidator::canonicalHash($a), EventValidator::canonicalHash($b));
        $this->assertNotSame(EventValidator::canonicalHash($a), EventValidator::canonicalHash($c), 'list order matters');
    }
}
